"""Write the command-line reference page from the CLI itself (ADR 0074).

``docs/guide/cli.md`` is generated, never edited by hand, so it cannot drift
from the code: a test fails when the page is out of date. To update it::

    uv run python -m modelbump.cli_reference > docs/guide/cli.md
"""

from collections.abc import Iterator
from enum import Enum
from pathlib import Path
from typing import Any

import typer

from modelbump.cli import app

HEADER = """# Command reference

<!-- Generated by `uv run python -m modelbump.cli_reference > docs/guide/cli.md`.
     Do not edit by hand: a test checks that this page matches the CLI. -->

Every command and option of `modelbump`, as `--help` shows them. New to
ModelBump? Start with the [tutorial](tutorial.md).
"""


def commands() -> Iterator[tuple[str, Any]]:
    """``(name, command)`` for every command, groups expanded, in help order."""
    yield from _walk(typer.main.get_command(app), [])


def _walk(command: Any, path: list[str]) -> Iterator[tuple[str, Any]]:
    subcommands = getattr(command, "commands", None)
    if subcommands is None:
        yield " ".join(["modelbump", *path]), command
        return
    for name, sub in subcommands.items():
        if not getattr(sub, "hidden", False):
            yield from _walk(sub, [*path, name])


def render() -> str:
    """The whole reference page, in Markdown."""
    parts = [HEADER, _index()]
    for name, command in commands():
        parts.append(_command(name, command))
    return "\n".join(parts).rstrip() + "\n"


def _index() -> str:
    lines = ["| Command | What it does |", "|---|---|"]
    for name, command in commands():
        anchor = name.replace(" ", "-")
        lines.append(f"| [`{name}`](#{anchor}) | {_first_line(command.help)} |")
    return "\n".join(lines) + "\n"


def _command(name: str, command: Any) -> str:
    lines = [f"## {name}", "", _text(command.help), ""]
    arguments = [p for p in command.params if p.param_type_name == "argument"]
    options = [p for p in command.params if p.param_type_name == "option"]
    usage = " ".join(
        [name, *(["[OPTIONS]"] if options else [])]
        + [p.name.upper() if p.required else f"[{p.name.upper()}]" for p in arguments]
    )
    lines += ["```text", usage, "```", ""]
    if arguments:
        lines += ["| Argument | Description | Default |", "|---|---|---|"]
        lines += [
            f"| `{p.name.upper()}` | {_cell(p.help)} | {_default(p.default, p.required)} |"
            for p in arguments
        ]
        lines.append("")
    if options:
        lines += ["| Option | Description | Default |", "|---|---|---|"]
        for p in options:
            names = ", ".join(f"`{o}`" for o in [*p.opts, *p.secondary_opts])
            lines.append(f"| {names} | {_cell(p.help)} | {_default(p.default, p.required)} |")
        lines.append("")
    return "\n".join(lines)


def _first_line(text: str | None) -> str:
    return _cell(_text(text).split("\n\n")[0])


def _text(text: str | None) -> str:
    """The docstring with its line breaks inside paragraphs joined."""
    paragraphs = (text or "").strip().split("\n\n")
    return "\n\n".join(" ".join(p.split()) for p in paragraphs)


def _cell(text: str | None) -> str:
    return " ".join((text or "").split()).replace("|", "\\|")


def _default(value: object, required: bool) -> str:
    if required:
        return "required"
    if value is None or value == () or value == []:
        return ""
    if isinstance(value, Enum):
        value = value.value
    if isinstance(value, bool):
        return "on" if value else "off"
    if isinstance(value, Path):
        value = value.as_posix()
    return f"`{value}`"


if __name__ == "__main__":  # pragma: no cover
    print(render(), end="")
